
import { Component, inject } from '@angular/core';
import {
  FormBuilder,
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import { RouterLink } from '@angular/router';
import {
  IonButton,
  IonCol,
  IonContent,
  IonGrid,
  IonIcon,
  IonInput,
  IonItem,
  IonLabel,
  IonList,
  IonRow,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { arrowForwardOutline } from 'ionicons/icons';
import { getLoginRoutePath, getRoutePath, loginRoutePath, forgotPasswordRoutePath } from '../../app.routes';
import { AuthService } from '../../common/auth/auth.service';
import { LoadingService } from '../../common/loading/loading.service';
import { LogoComponent } from '../../common/logo/logo.component';

@Component({
    selector: 'app-login-with-email',
    templateUrl: './login-with-email.page.html',
    styleUrls: ['./login-with-email.page.scss'],
    imports: [
    IonContent,
    IonList,
    IonItem,
    IonLabel,
    IonInput,
    IonButton,
    IonGrid,
    IonRow,
    IonCol,
    ReactiveFormsModule,
    RouterLink,
    IonIcon,
    LogoComponent
]
})
export class LoginWithEmailPage {
  form: FormGroup<LoginFormControls> = inject(FormBuilder).group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(8)]],
  });

  readonly loginRouterLink = [getRoutePath(loginRoutePath)];
  readonly forgotPasswordRouterLink = [getLoginRoutePath(forgotPasswordRoutePath)];

  private readonly authService = inject(AuthService);
  private readonly loadingService = inject(LoadingService);

  constructor() {
    addIcons({ arrowForwardOutline });
  }

  async handleLogin(event: any) {
    event.preventDefault();

    this.loadingService.setLoading(true);

    const credentials = this.form.value as LoginFormValue;
    await this.authService.signIn(credentials);

    this.loadingService.setLoading(false);
  }
}

type LoginFormControl = FormControl<string | null>;
type LoginFormControls = LoginUpForm<LoginFormControl>;
type LoginFormValue = LoginUpForm<string>;

interface LoginUpForm<T extends string | FormControl<string | null>> {
  email: T;
  password: T;
}
